@layer moduix.components {
  .root {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-switch-gap, var(--moduix-spacing-2));
    width: fit-content;
    vertical-align: middle;
    cursor: pointer;

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-disabled] {
      opacity: var(--moduix-switch-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .control {
    box-sizing: border-box;
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    width: var(--_switch-width, 2.75rem);
    height: var(--_switch-height, var(--moduix-size-xs));
    --_switch-thumb-translate-default: calc(
      var(--_switch-width, 2.75rem) - var(--_switch-thumb-size, var(--moduix-spacing-5)) -
        (var(--moduix-switch-padding, var(--moduix-spacing-0-5)) * 2) -
        (var(--moduix-switch-border-width, var(--moduix-border-width-sm)) * 2)
    );
    border: var(--moduix-switch-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-switch-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-switch-radius, var(--moduix-radius-full));
    padding: var(--moduix-switch-padding, var(--moduix-spacing-0-5));
    background-color: var(--moduix-switch-bg, var(--moduix-color-muted));
    outline: 0;
    line-height: 0;
    user-select: none;
    transition:
      background-color var(--moduix-switch-transition, var(--moduix-transition-default)),
      border-color var(--moduix-switch-transition, var(--moduix-transition-default)),
      opacity var(--moduix-switch-transition, var(--moduix-transition-default));

    &[data-state='checked'] {
      border-color: var(--moduix-switch-border-color-checked, var(--moduix-color-primary));
      background-color: var(--moduix-switch-bg-checked, var(--moduix-color-primary));
    }

    &[data-invalid] {
      border-color: var(--moduix-switch-border-color-invalid, var(--moduix-color-destructive));
    }

    &[data-focus-visible] {
      outline: var(
          --moduix-switch-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-switch-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-switch-focus-ring-offset, var(--moduix-border-width-sm));
    }

    @media (hover: hover) {
      &[data-state='unchecked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(--moduix-switch-bg-hover, var(--moduix-color-accent));
      }

      &[data-state='checked'][data-hover]:not([data-readonly], [data-disabled]) {
        background-color: var(
          --moduix-switch-bg-checked-hover,
          var(--moduix-switch-bg-checked, var(--moduix-color-primary))
        );
      }
    }
  }

  .root[data-size='xs'] .control {
    --_switch-width: var(--moduix-switch-width-xs, 1.75rem);
    --_switch-height: var(--moduix-switch-height-xs, 1rem);
    --_switch-thumb-size: var(--moduix-switch-thumb-size-xs, var(--moduix-spacing-3));
  }

  .root[data-size='sm'] .control {
    --_switch-width: var(--moduix-switch-width-sm, 2.25rem);
    --_switch-height: var(--moduix-switch-height-sm, 1.25rem);
    --_switch-thumb-size: var(--moduix-switch-thumb-size-sm, var(--moduix-spacing-4));
  }

  .root[data-size='md'] .control {
    --_switch-width: var(--moduix-switch-width-md, 2.75rem);
    --_switch-height: var(--moduix-switch-height-md, var(--moduix-size-xs));
    --_switch-thumb-size: var(--moduix-switch-thumb-size-md, var(--moduix-spacing-5));
  }

  .root[data-size='lg'] .control {
    --_switch-width: var(--moduix-switch-width-lg, 3.25rem);
    --_switch-height: var(--moduix-switch-height-lg, 1.75rem);
    --_switch-thumb-size: var(--moduix-switch-thumb-size-lg, var(--moduix-size-xs));
  }

  .root[data-size='xl'] .control {
    --_switch-width: var(--moduix-switch-width-xl, 3.75rem);
    --_switch-height: var(--moduix-switch-height-xl, var(--moduix-size-sm));
    --_switch-thumb-size: var(--moduix-switch-thumb-size-xl, var(--moduix-spacing-7));
  }

  .thumb {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--_switch-thumb-size, var(--moduix-spacing-5));
    height: var(--_switch-thumb-size, var(--moduix-spacing-5));
    border: var(--moduix-switch-thumb-border-width, 0) solid
      var(--moduix-switch-thumb-border-color, transparent);
    border-radius: var(--moduix-switch-thumb-radius, var(--moduix-radius-full));
    background-color: var(
      --moduix-switch-thumb-bg-unchecked,
      var(--moduix-switch-thumb-bg, var(--moduix-color-background))
    );
    color: var(
      --moduix-switch-thumb-color-unchecked,
      var(--moduix-switch-thumb-color, var(--moduix-color-muted))
    );
    box-shadow: var(--moduix-switch-thumb-shadow, var(--moduix-shadow-sm));
    transform: translateX(0);
    transition:
      transform
        var(
          --moduix-switch-thumb-transition,
          var(--moduix-switch-transition, var(--moduix-transition-default))
        ),
      background-color var(--moduix-switch-transition, var(--moduix-transition-default)),
      color var(--moduix-switch-transition, var(--moduix-transition-default));

    &[data-state='checked'] {
      background-color: var(
        --moduix-switch-thumb-bg-checked,
        var(--moduix-switch-thumb-bg, var(--moduix-color-primary-foreground))
      );
      color: var(
        --moduix-switch-thumb-color-checked,
        var(--moduix-switch-thumb-color, var(--moduix-color-primary))
      );
      transform: translateX(
        var(--moduix-switch-thumb-translate, var(--_switch-thumb-translate-default))
      );
    }

    & > svg {
      display: block;
      width: var(--moduix-switch-thumb-icon-size, 65%);
      height: var(--moduix-switch-thumb-icon-size, 65%);
      flex-shrink: 0;
    }
  }

  .root:dir(rtl) .thumb[data-state='checked'] {
    transform: translateX(
      calc(var(--moduix-switch-thumb-translate, var(--_switch-thumb-translate-default)) * -1)
    );
  }

  .label {
    color: var(--moduix-switch-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-switch-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-switch-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-switch-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .control,
    .thumb {
      transition: none;
    }
  }
}

import { SwitchContext, SwitchHiddenInput, useSwitch, useSwitchContext } from '@ark-ui/vue/switch';
import Switch from './Switch.vue';
import SwitchControl from './SwitchControl.vue';
import SwitchLabel from './SwitchLabel.vue';
import SwitchRootProvider from './SwitchRootProvider.vue';
import SwitchThumb from './SwitchThumb.vue';

export {
  Switch,
  SwitchContext,
  SwitchControl,
  SwitchHiddenInput,
  SwitchLabel,
  SwitchRootProvider,
  SwitchThumb,
  useSwitch,
  useSwitchContext,
};

export type {
  SwitchCheckedChangeDetails,
  SwitchContextProps,
  SwitchControlProps,
  SwitchHiddenInputProps,
  SwitchLabelProps,
  SwitchRootEmits,
  UseSwitchContext,
  UseSwitchProps,
  UseSwitchReturn,
} from '@ark-ui/vue/switch';

export type { Props as SwitchRootProps, SwitchSize } from './Switch.vue';
export type { Props as SwitchRootProviderProps } from './SwitchRootProvider.vue';
